//! Fixed encodings of the types that peers send and that the databases
//! hold. A change to one of these bytes makes old datadirs unreadable, or
//! splits the network.

use bitcoin::hashes::Hash as _;

use crate::{
    state::{
        decisions::{DecisionId, DecisionType},
        markets::{DimensionSpec, MarketId},
    },
    types::{
        Address, BitcoinOutputContent, Block, BlockHash, Body,
        ClaimDecisionPayload, DecisionClaimEntry, FilledOutput,
        FilledOutputContent, Header, InPoint, M6id, MerkleRoot, OutPoint,
        OutPointKey, Output, OutputContent, SpentOutput, Transaction,
        TransactionData, Txid, WithdrawalOutputContent,
    },
};

fn outpoints() -> [OutPoint; 5] {
    [
        OutPoint::Regular {
            txid: Txid([1; 32]),
            vout: 2,
        },
        OutPoint::Coinbase {
            merkle_root: MerkleRoot::from([3; 32]),
            vout: 4,
        },
        OutPoint::Deposit(bitcoin::OutPoint {
            txid: bitcoin::Txid::from_byte_array([5; 32]),
            vout: 6,
        }),
        OutPoint::MarketFunds {
            market_id: [7; 6],
            block_height: 8,
            is_fee: true,
        },
        OutPoint::Payout {
            hash: MerkleRoot::from([9; 32]),
            vout: 10,
        },
    ]
}

fn withdrawal_address()
-> anyhow::Result<bitcoin::Address<bitcoin::address::NetworkUnchecked>> {
    Ok("bc1qar0srrr7xfkvy5l643lydnw9re59gtzzwf5mdq".parse()?)
}

fn outputs() -> anyhow::Result<[Output; 3]> {
    Ok([
        Output::new(
            Address([11; 20]),
            OutputContent::Bitcoin(BitcoinOutputContent(
                bitcoin::Amount::from_sat(12),
            )),
        ),
        Output {
            address: Address([13; 20]),
            content: OutputContent::Withdrawal(WithdrawalOutputContent {
                value: bitcoin::Amount::from_sat(14),
                main_fee: bitcoin::Amount::from_sat(15),
                main_address: withdrawal_address()?,
            }),
            memo: vec![16, 17],
        },
        Output::new(
            Address([18; 20]),
            OutputContent::MarketFunds {
                market_id: [19; 6],
                amount: BitcoinOutputContent(bitcoin::Amount::from_sat(20)),
                is_fee: false,
            },
        ),
    ])
}

fn transactions() -> anyhow::Result<[Transaction; 2]> {
    let [regular, coinbase, deposit, market_funds, payout] = outpoints();
    let trade = Transaction {
        inputs: vec![regular, coinbase, deposit],
        outputs: outputs()?.to_vec(),
        memo: vec![21],
        data: Some(TransactionData::Trade {
            market_id: MarketId::new([22; 6]),
            outcome_index: 23,
            shares: -24,
            trader: Address([25; 20]),
            limit_sats: 26,
            tx_pow_nonce: Some(27),
            prev_block_hash: BlockHash([28; 32]),
        }),
    };
    let create_market = Transaction {
        inputs: vec![market_funds, payout],
        outputs: Vec::new(),
        memo: Vec::new(),
        data: Some(TransactionData::CreateMarket {
            title: "title".to_owned(),
            description: "description".to_owned(),
            dimension_specs: vec![
                DimensionSpec::Single(DecisionId::new(true, 1, 0)?),
                DimensionSpec::Categorical(DecisionId::new(false, 2, 3)?),
            ],
            new_claims: vec![ClaimDecisionPayload {
                decision_type: DecisionType::Scaled {
                    min: 0.0,
                    max: 100.0,
                    increment: 0.5,
                },
                decisions: vec![DecisionClaimEntry {
                    decision_id_bytes: [0x81, 0, 0],
                    header: "header".to_owned(),
                    description: "description".to_owned(),
                    option_0_label: Some("no".to_owned()),
                    option_1_label: None,
                    option_labels: Some(vec!["a".to_owned(), "b".to_owned()]),
                    tags: None,
                }],
            }],
            trading_fee: Some(0.01),
            tx_pow_hash_selector: Some(29),
            tx_pow_ordering: None,
            tx_pow_difficulty: Some(30),
        }),
    };
    Ok([trade, create_market])
}

fn block() -> anyhow::Result<Block> {
    let header = Header {
        merkle_root: MerkleRoot::from([31; 32]),
        prev_side_hash: Some(BlockHash([32; 32])),
        prev_main_hash: bitcoin::BlockHash::from_byte_array([33; 32]),
    };
    let body = Body {
        coinbase: outputs()?.to_vec(),
        transactions: transactions()?.to_vec(),
        authorizations: Vec::new(),
        actor_proofs: vec![None, None],
    };
    Ok(Block {
        header,
        body,
        height: 34,
    })
}

fn filled_outputs() -> anyhow::Result<[FilledOutput; 3]> {
    Ok([
        FilledOutput::new(
            Address([35; 20]),
            FilledOutputContent::Bitcoin(BitcoinOutputContent(
                bitcoin::Amount::from_sat(36),
            )),
        ),
        FilledOutput::new(
            Address([37; 20]),
            FilledOutputContent::BitcoinWithdrawal(WithdrawalOutputContent {
                value: bitcoin::Amount::from_sat(38),
                main_fee: bitcoin::Amount::from_sat(39),
                main_address: withdrawal_address()?,
            }),
        ),
        FilledOutput::new(
            Address([40; 20]),
            FilledOutputContent::MarketFunds {
                market_id: [41; 6],
                amount: BitcoinOutputContent(bitcoin::Amount::from_sat(42)),
                is_fee: true,
            },
        ),
    ])
}

/// Borsh, bincode and database key encodings of each outpoint, as hex
#[test]
fn outpoint_encodings() -> anyhow::Result<()> {
    const EXPECTED: [&str; 15] = [
        "00010101010101010101010101010101010101010101010101010101010101010102000000",
        "00000000010101010101010101010101010101010101010101010101010101010101010102000000",
        "00010101010101010101010101010101010101010101010101010101010101010102000000",
        "01030303030303030303030303030303030303030303030303030303030303030304000000",
        "01000000030303030303030303030303030303030303030303030303030303030303030304000000",
        "01030303030303030303030303030303030303030303030303030303030303030304000000",
        "02050505050505050505050505050505050505050505050505050505050505050506000000",
        "020000002000000000000000050505050505050505050505050505050505050505050505050505050505050506000000",
        "02050505050505050505050505050505050505050505050505050505050505050506000000",
        "030707070707070800000001",
        "030000000707070707070800000001",
        "03070707070707080000000100000000000000000000000000000000000000000000000000",
        "0409090909090909090909090909090909090909090909090909090909090909090a000000",
        "0400000009090909090909090909090909090909090909090909090909090909090909090a000000",
        "0409090909090909090909090909090909090909090909090909090909090909090a000000",
    ];
    let mut encodings = Vec::new();
    for outpoint in outpoints() {
        encodings.push(const_hex::encode(borsh::to_vec(&outpoint)?));
        encodings.push(const_hex::encode(bincode::serialize(&outpoint)?));
        encodings.push(const_hex::encode(OutPointKey::from(&outpoint)));
    }
    assert_eq!(encodings, EXPECTED);
    Ok(())
}

/// Txid, borsh and bincode encodings of each transaction, as hex
#[test]
fn transaction_encodings() -> anyhow::Result<()> {
    const EXPECTED: [&str; 6] = [
        "62145150cd365272f1e3e4b40010c6666a610e390832c99b6bf31fec49cfe8a6",
        "",
        "",
        "e634cf2928d7a81049f20f43e5d215f12a80598647c8dde9a60b6cc0284ec3d7",
        "",
        "",
    ];
    let mut encodings = Vec::new();
    for tx in transactions()? {
        encodings.push(tx.txid().to_string());
        encodings.push(const_hex::encode(borsh::to_vec(&tx)?));
        encodings.push(const_hex::encode(bincode::serialize(&tx)?));
    }
    assert_eq!(encodings, EXPECTED);
    Ok(())
}

