/// Bincode encoding of each spent output, as the stxo database holds it
#[test]
fn spent_output_encodings() -> anyhow::Result<()> {
    const EXPECTED: [&str; 3] = [
        "232323232323232323232323232323232323232300000000240000000000000000000000000000000100000020000000000000002b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b",
        "252525252525252525252525252525252525252501000000260000000000000027000000000000002a0000000000000062633171617230737272723778666b7679356c3634336c79646e77397265353967747a7a7766356d647100000000000000000100000020000000000000002b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b",
        "2828282828282828282828282828282828282828020000002929292929292a000000000000000100000000000000000100000020000000000000002b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b",
    ];
    let mut encodings = Vec::new();
    for output in filled_outputs()? {
        let spent_output = SpentOutput {
            output,
            inpoint: InPoint::Withdrawal {
                m6id: M6id(bitcoin::Txid::from_byte_array([43; 32])),
            },
        };
        encodings.push(const_hex::encode(bincode::serialize(&spent_output)?));
    }
    assert_eq!(encodings, EXPECTED);
    Ok(())
}
